contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val) public payable {
        require(true);

        uint minBefore = c.MinSum(); if (__ESBMC_reverted()) return;
        bool reverted;

        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint minAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!reverted ? minAfter == val : minAfter == minBefore);
    }

    receive() external payable {}
}

